declare change jsonb=$change${"trail":{"id":10,"slug":"krivan-tri-studnicky-loop","peak_id":150,"peak_slug":"krivan"},"before":{"row":{"id":6,"trail_id":10,"address":"Tri studni\u010dky, Vysok\u00e9 Tatry, Slovakia","postcode":null,"latitude":null,"longitude":null,"google_maps_url":null,"public_transport_url":"https://slovakia.travel/en/the-krivan-mt-the-high-tatras","source_url":"https://slovakia.travel/en/the-krivan-mt-the-high-tatras","last_verified_at":"2026-10-26T17:54:20.294368+00:00","active":true,"created_at":"2026-10-26T17:54:20.294368+00:00"},"i18n":[{"lang":"en","warnings":"This is a demanding high-mountain route. The restored trail from Tri studni\u010dky reopened on 9 October 2026. Check current TANAP notices before travelling because seasonal and temporary closures may apply.","access_id":6,"directions":"The route starts at Tri studni\u010dky in the High Tatras. The official route description identifies Tri studni\u010dky as both the starting and finishing point.","public_transport":"A bus stop is located at Tri studni\u010dky according to the official route information."},{"lang":"pl","warnings":"Jest to wymagaj\u0105ca trasa wysokog\u00f3rska. Odnowiony szlak z Tri studni\u010dky zosta\u0142 ponownie otwarty 9 pa\u017adziernika 2026. Przed wyjazdem sprawd\u017a aktualne komunikaty TANAP, poniewa\u017c mog\u0105 obowi\u0105zywa\u0107 sezonowe lub tymczasowe zamkni\u0119cia.","access_id":6,"directions":"Trasa rozpoczyna si\u0119 przy Tri studni\u010dky w Tatrach Wysokich. Oficjalny opis wskazuje Tri studni\u010dky jako punkt pocz\u0105tkowy i ko\u0144cowy trasy.","public_transport":"Wed\u0142ug oficjalnych informacji o trasie przy Tri studni\u010dky znajduje si\u0119 przystanek autobusowy."},{"lang":"ua","warnings":"\u0426\u0435 \u0441\u043a\u043b\u0430\u0434\u043d\u0438\u0439 \u0432\u0438\u0441\u043e\u043a\u043e\u0433\u0456\u0440\u043d\u0438\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442. \u0412\u0456\u0434\u043d\u043e\u0432\u043b\u0435\u043d\u0443 \u0441\u0442\u0435\u0436\u043a\u0443 \u0432\u0456\u0434 Tri studni\u010dky \u0437\u043d\u043e\u0432\u0443 \u0432\u0456\u0434\u043a\u0440\u0438\u043b\u0438 9 \u0436\u043e\u0432\u0442\u043d\u044f 2026 \u0440\u043e\u043a\u0443. \u041f\u0435\u0440\u0435\u0434 \u043f\u043e\u0457\u0437\u0434\u043a\u043e\u044e \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0456 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f TANAP \u0449\u043e\u0434\u043e \u0441\u0435\u0437\u043e\u043d\u043d\u0438\u0445 \u0456 \u0442\u0438\u043c\u0447\u0430\u0441\u043e\u0432\u0438\u0445 \u043e\u0431\u043c\u0435\u0436\u0435\u043d\u044c.","access_id":6,"directions":"\u041c\u0430\u0440\u0448\u0440\u0443\u0442 \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0431\u0456\u043b\u044f Tri studni\u010dky \u0443 \u0412\u0438\u0441\u043e\u043a\u0438\u0445 \u0422\u0430\u0442\u0440\u0430\u0445. \u041e\u0444\u0456\u0446\u0456\u0439\u043d\u0438\u0439 \u043e\u043f\u0438\u0441 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443 \u0432\u043a\u0430\u0437\u0443\u0454 Tri studni\u010dky \u044f\u043a \u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0443 \u0442\u0430 \u043a\u0456\u043d\u0446\u0435\u0432\u0443 \u0442\u043e\u0447\u043a\u0443.","public_transport":"\u0417\u0433\u0456\u0434\u043d\u043e \u0437 \u043e\u0444\u0456\u0446\u0456\u0439\u043d\u043e\u044e \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u0454\u044e \u043f\u0440\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442, \u0431\u0456\u043b\u044f Tri studni\u010dky \u0454 \u0430\u0432\u0442\u043e\u0431\u0443\u0441\u043d\u0430 \u0437\u0443\u043f\u0438\u043d\u043a\u0430."},{"lang":"zh","warnings":"\u8fd9\u662f\u4e00\u6761\u5177\u6709\u6311\u6218\u6027\u7684\u9ad8\u5c71\u8def\u7ebf\u3002\u4ece Tri studni\u010dky \u51fa\u53d1\u7684\u4fee\u590d\u6b65\u9053\u5df2\u4e8e2026\u5e7410\u67089\u65e5\u91cd\u65b0\u5f00\u653e\u3002\u51fa\u884c\u524d\u8bf7\u67e5\u770b TANAP \u6700\u65b0\u516c\u544a\uff0c\u56e0\u4e3a\u53ef\u80fd\u5b58\u5728\u5b63\u8282\u6027\u6216\u4e34\u65f6\u5173\u95ed\u3002","access_id":6,"directions":"\u8def\u7ebf\u4ece\u9ad8\u5854\u7279\u62c9\u5c71\u8109\u7684 Tri studni\u010dky \u51fa\u53d1\u3002\u5b98\u65b9\u8def\u7ebf\u8d44\u6599\u5c06 Tri studni\u010dky \u5217\u4e3a\u8def\u7ebf\u7684\u8d77\u70b9\u548c\u7ec8\u70b9\u3002","public_transport":"\u6839\u636e\u5b98\u65b9\u8def\u7ebf\u4fe1\u606f\uff0cTri studni\u010dky \u8bbe\u6709\u516c\u4ea4\u8f66\u7ad9\u3002"}]},"after":{"source_url":"https://www.tanap.sk/od-1-novembra-sa-v-tatranskom-narodnom-parku-zacina-sezonna-uzavera-9441/","last_verified_at":"2026-11-22T00:00:00Z","warnings":{"pl":"Zamkni\u0119cie dla zwyk\u0142ej turystyki pieszej: 1 listopada 2026 \u2013 31 maja 2027. Obejmuje wej\u015bcie z Tri studni\u010dky oraz odcinek od Jamsk\u00e9ho plesa na Krywa\u0144. Plik GPX nie oznacza, \u017ce szlak jest otwarty. Przed wyj\u015bciem sprawd\u017a aktualny komunikat TANAP.","en":"Closed to ordinary hiking from 1 November 2026 to 31 May 2027, including the Tri studni\u010dky ascent and the section from Jamsk\u00e9 pleso to Kriv\u00e1\u0148. A GPX file does not confirm access. Check the latest TANAP notice before setting off.","ua":"\u0417\u0430\u043a\u0440\u0438\u0442\u043e \u0434\u043b\u044f \u0437\u0432\u0438\u0447\u0430\u0439\u043d\u0438\u0445 \u043f\u0456\u0448\u0438\u0445 \u043f\u043e\u0445\u043e\u0434\u0456\u0432 \u0432\u0456\u0434 1 \u043b\u0438\u0441\u0442\u043e\u043f\u0430\u0434\u0430 2026 \u0434\u043e 31 \u0442\u0440\u0430\u0432\u043d\u044f 2027, \u0437\u043e\u043a\u0440\u0435\u043c\u0430 \u043f\u0456\u0434\u0439\u043e\u043c \u0456\u0437 Tri studni\u010dky \u0442\u0430 \u0432\u0456\u0434\u0440\u0456\u0437\u043e\u043a \u0432\u0456\u0434 Jamsk\u00e9 pleso \u043d\u0430 Kriv\u00e1\u0148. \u041d\u0430\u044f\u0432\u043d\u0456\u0441\u0442\u044c GPX \u043d\u0435 \u043e\u0437\u043d\u0430\u0447\u0430\u0454, \u0449\u043e \u0441\u0442\u0435\u0436\u043a\u0430 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0430. \u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0445\u043e\u0434\u043e\u043c \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f TANAP.","zh":"\u666e\u901a\u5f92\u6b65\u5b63\u8282\u6027\u5c01\u95ed\uff1a2026\u5e7411\u67081\u65e5\u81f32027\u5e745\u670831\u65e5\uff0c\u5305\u62ec\u4eceTri studni\u010dky\u4e0a\u5c71\u53ca\u4eceJamsk\u00e9 pleso\u524d\u5f80Kriv\u00e1\u0148\u7684\u8def\u6bb5\u3002\u63d0\u4f9bGPX\u6587\u4ef6\u5e76\u4e0d\u4ee3\u8868\u8def\u7ebf\u5f00\u653e\u3002\u51fa\u53d1\u524d\u8bf7\u67e5\u770bTANAP\u6700\u65b0\u516c\u544a\u3002"}},"sources":[{"kind":"notice","url":"https://www.tanap.sk/od-1-novembra-sa-v-tatranskom-narodnom-parku-zacina-sezonna-uzavera-9441/","checked_on":"2026-11-22","status":200,"sha256":"169290c638fb232934e4d99228d7fffa68c44e315cc81a264ff016d8ff6a832b"},{"kind":"visitor_rules","url":"https://www.tanap.sk/wp-content/uploads/navstevny_poriadok_tanapu.pdf","checked_on":"2026-11-22","status":200,"sha256":"09fe064f86ed0544953abb94885691567b2d4760dbf4171e506c1d76a92f855c"}],"scope":"TANAP visitor rules section 4(2)(b)(1), Annex 3 part A item 17; hiking restrictions for the 2026/2027 season"}$change$::jsonb; receipt jsonb; actual jsonb; expected jsonb; previous jsonb; result jsonb; txt jsonb;
 target_id bigint;
begin
 if current_user in ('anon','authenticated') then raise exception 'Owner execution required'; end if;
 perform pg_advisory_xact_lock(261122,2);
 lock table public.trail_access,public.trail_access_i18n in share row exclusive mode;
 if not exists(select from pg_class where oid='public.trail_access'::regclass and relrowsecurity) or not exists(select from pg_class where oid='public.trail_access_i18n'::regclass and relrowsecurity) then raise exception 'Practical RLS missing'; end if;
 target_id=(change->'before'->'row'->>'id')::bigint;
 if (select count(*) from public.trail_access where trail_id=10)<>1 then raise exception 'Unexpected access card count'; end if;
 perform 1 from public.trails t join public.peaks p on p.id=t.peak_id where t.id=10 and t.slug='krivan-tri-studnicky-loop' and t.peak_id=150 and t.active and p.slug='krivan' and p.active for update of t,p;
 if not found then raise exception 'Krivan route identity changed'; end if;
 select snapshot into receipt from peakguide_private.catalogue_batch_receipts where batch_key='krivan-seasonal-01' for update;

 select jsonb_build_object('row',to_jsonb(a),'i18n',(select jsonb_agg(to_jsonb(i) order by lang collate "C") from public.trail_access_i18n i where i.access_id=a.id)) into actual from public.trail_access a where a.id=target_id;
 if receipt is null then raise notice 'Seasonal patch not applied'; return; end if;

 if receipt->>'manifest_sha256'<>'252cb41f8d23fc7be5f2883b2f12b5ec547aaed0eba5f1200204ec72a0dc4222' or receipt->>'version'<>'1' then raise exception 'Different seasonal receipt'; end if;
 if actual is distinct from receipt->'after' then raise exception 'Seasonal card changed since patch'; end if;

 update public.trail_access set source_url=receipt->'before'->'row'->>'source_url',last_verified_at=(receipt->'before'->'row'->>'last_verified_at')::timestamptz where id=target_id;
 for txt in select value from jsonb_array_elements(receipt->'before'->'i18n') loop
  update public.trail_access_i18n set warnings=txt->>'warnings' where access_id=target_id and lang=txt->>'lang';
 end loop;

 select jsonb_build_object('row',to_jsonb(a),'i18n',(select jsonb_agg(to_jsonb(i) order by lang collate "C") from public.trail_access_i18n i where i.access_id=a.id)) into actual from public.trail_access a where a.id=target_id;

 if actual is distinct from receipt->'before' then raise exception 'Unexpected seasonal rollback side effect'; end if;
 delete from peakguide_private.catalogue_batch_receipts where batch_key='krivan-seasonal-01';
 raise notice 'Restored the reviewed warning/source/date only';
end $patch$;
commit;
